    # Use integer compositions: number of solutions to r1+r2+...+rn = N where each ri >= 1
    def compositions(n, k):
        if k == 1:
            yield n
            return
        for i in range(1, n - k + 2):
            for tail in compositions(n - i, k - 1):
                yield i, *tail

    return list(compositions(num_rows, num_groups))

